from dataclasses import dataclass

# Value Object (Immutable, no identity)
@dataclass(frozen=True)
class Money:
    amount: float
    currency: str

# Entity (Has identity)
class Account:
    def __init__(self, account_id: str, balance: Money):
        self.account_id = account_id
        self.balance = balance

